  static String normalize(String s) =>
      s.replaceAll(RegExp(r'[\s\n\r]+'), '');

  /// Re-asocia filas CSV cuya clave perdió saltos de línea.
  static Map<String, String> align(Map<String, String> csv) {
    final byNorm = <String, String>{};
    csv.forEach((k, v) {
      byNorm[normalize(k)] = v;
    });
    final out = Map<String, String>.from(csv);
    for (final key in values) {
      if (out.containsKey(key)) continue;
      final n = normalize(key);
      final mapped = byNorm[n];
      if (mapped != null) out[key] = mapped;
    }
    return out;
  }
